mapper.select:
SELECT COUNT(1)
FROM orders o
INNER JOIN order_item oi ON oi.order_id = o.id
INNER JOIN product_sku sku ON sku.id = oi.sku_id AND sku.product_id = oi.product_id
WHERE o.id = #{orderId}
  AND o.created_by = #{username}
  AND o.order_status IN ('DELIVERED', 'RECEIVED', 'COMPLETED')
  AND oi.product_id = #{productId}
  AND oi.sku_id = #{skuId}
